    #[test]
    fn locked_async_locks_inside_the_future_not_on_the_caller() {
        let code = emit_src(
            r#"
            #[bridge(locked)] pub struct Cache { x: i32 }
            #[bridge] impl Cache {
                pub fn put(&mut self) {}
            }
            "#,
        );
        let spawn = code.split("fn spawn_#_put").nth(1).unwrap();
        // The route, not just the split: a locked member goes to the executor
        // even though `put` is a plain `fn` with nothing to await. This is the
        // assertion that fails if someone "simplifies" the branch back to
        // `f.rust_async`.
        assert!(
            spawn.contains("frustrate::executor::spawn(call_id, async move {"),
            "a locked member must dispatch through the executor: {spawn}"
        );
        assert!(
            !spawn.contains("pool::spawn_call"),
            "a locked member must not take the pool arm: {spawn}"
        );
        let pre_spawn = spawn.split("executor::spawn").next().unwrap();
        assert!(pre_spawn.contains("locked_arc"), "arc clone must happen on caller: {spawn}");
        assert!(!pre_spawn.contains(".write()"), "lock must NOT be taken on caller: {spawn}");
        let in_future = spawn.split("executor::spawn").nth(1).unwrap();
        assert!(in_future.contains(".write()"), "lock must be taken in the future: {spawn}");
        // The body is a plain `fn`; awaiting it would not compile.
        assert!(
            in_future.contains("let ret = crate::api::Cache::put(&mut *guard_this);"),
            "a non-`async fn` body must not be awaited: {spawn}"
        );
    }

    /// The two halves of the executor arm, told apart. A `rust_async` body is a
    /// future and carries `.await`; a locked plain `fn` body does not, and is
    /// there only so its lock acquisition can suspend the task. Both are the
    /// same emitted shape otherwise, which is exactly why one test asserting
    /// "goes to the executor" would not notice the `.await` going missing from
    /// the wrong one.
    /// A sync member on a locked `dyn` trait that also takes a locked trait
    /// parameter. `locked_acquisitions` counts both, so the receiver takes the
    /// *planned* path and defers its guard to `emit_lock_plan` — and the sync
    /// trait arm used to bind its own guard inline without joining the plan.
    /// With one entry the plan returns early, so `guard_this` was never bound
    /// and the emitted Rust did not compile. Found by generating the shape
    /// rather than by anyone thinking of it.
    #[test]
    fn a_sync_dyn_receiver_beside_a_dyn_param_binds_both_guards() {
        let code = emit_src(
            r#"
            #[bridge(locked)] pub trait Store: Send + Sync {
                #[bridge(sync, on_contention = "error")]
                fn probe(&self, other: &dyn Store) -> i64;
            }
            "#,
        );
        let call = code.split("fn call_#_probe").nth(1).unwrap();
        // Both guards are bound before the invocation names them.
        assert!(call.contains("guard_this ="), "receiver guard must be bound: {call}");
        assert!(call.contains("guard_other ="), "parameter guard must be bound: {call}");
        // And through the plan, since there are two acquisitions to order.
        assert!(call.contains("handle::lock_plan(&mut plan)"), "{call}");
        let invoke = call.find("Store::probe(").expect("invokes");
        for g in ["guard_this =", "guard_other ="] {
            assert!(
                call.find(g).expect("bound") < invoke,
                "{g} must be bound before the invocation: {call}"
            );
        }
    }

    #[test]
    fn only_a_rust_async_body_is_awaited_in_the_future() {
        let locked_async_fn = emit_src(
            r#"
            #[bridge(locked)] pub struct Cache { x: i32 }
            #[bridge] impl Cache {
                pub async fn slow(&self) -> i32 { self.x }
            }
            "#,
        );
        let spawn = locked_async_fn.split("fn spawn_#_slow").nth(1).unwrap();
        assert!(
            spawn.contains("let ret = crate::api::Cache::slow(&*guard_this).await;"),
            "an `async fn` body must be awaited: {spawn}"
        );
        // A free `async fn` (no lock) still reaches the same arm by the other
        // half of the condition.
        let free = emit_src("#[bridge] pub async fn f(x: i64) -> i64 { x }");
        assert!(free.contains("frustrate::executor::spawn"), "{free}");
        assert!(free.contains("let ret = crate::api::f(x).await;"), "{free}");
        // A plain free function with no lock keeps the pool arm — the reroute
        // is scoped to locked members, not to every dispatched one.
        let plain = emit_src("#[bridge] pub fn g(x: i64) -> i64 { x }");
        assert!(plain.contains("frustrate::pool::spawn_call"), "{plain}");
        assert!(!plain.contains("executor::spawn"), "{plain}");
    }

    /// Every generated request decode asserts the request was fully consumed
    /// — the mirror of the `r.assertConsumed()` generated Dart emits after a
    /// response decode. Position matters as much as presence: the assert has
    /// to sit after the LAST argument read and before the user body, so a
    /// trailing-byte request is refused before anything runs and the panic is
    /// attributed to the caller's thread rather than a pool worker's.
    #[test]
    fn sync_call_asserts_the_request_was_fully_consumed() {
        let code = emit_src("#[bridge(sync)] pub fn add(a: i32, b: i32) -> i32 { a + b }");
        let body = code.split("fn call_#_add").nth(1).unwrap();
        let last_read = body.find("let b = r.read_i32()").expect("decodes b");
        let assert_at = body.find("r.assert_consumed();").expect("asserts consumed");
        let invoke_at = body.find("crate::api::add(a, b)").expect("invokes");
        assert!(last_read < assert_at && assert_at < invoke_at, "{body}");
    }

    /// The async path must assert on the CALLER, not inside the pool/executor
    /// closure: the prelude decode already runs there (while the Dart handles
    /// are guaranteed alive), and a panic from inside the closure would be
    /// attributed through the pool's trap path instead of the issue path.
    #[test]
    fn async_spawn_asserts_on_the_caller_before_spawning() {
        let code = emit_src("#[bridge] pub fn f(x: i64) {}");
        let body = code.split("fn spawn_#_f").nth(1).unwrap();
        let read_at = body.find("let x = r.read_i64()").expect("decodes x");
        let assert_at = body.find("r.assert_consumed();").expect("asserts consumed");
        let spawn_at = body.find("pool::spawn_call").expect("spawns");
        assert!(read_at < assert_at && assert_at < spawn_at, "{body}");
    }

    /// A bridged `async fn` hands its body to the cooperative executor rather
    /// than the pool; the assert stays on the caller there too.
    #[test]
    fn rust_async_spawn_asserts_before_handing_to_the_executor() {
        let code = emit_src("#[bridge] pub async fn f(x: i64) {}");
        let body = code.split("fn spawn_#_f").nth(1).unwrap();
        let assert_at = body.find("r.assert_consumed();").expect("asserts consumed");
        let spawn_at = body.find("executor::spawn").expect("spawns on the executor");
        assert!(assert_at < spawn_at, "{body}");
    }

    /// Actor members decode on the actor's executor, through their own
    /// entry (`frustrate_actor_call` natively, the wasm arm of
    /// `frustrate_call_async` in a worker) — the transport whose request
    /// crosses a `postMessage`, so the one that most needs this.
    #[test]
    fn actor_call_asserts_the_request_was_fully_consumed() {
        let code = emit_src(
            r#"
            #[bridge(actor)] pub struct Miner { n: i64 }
            #[bridge] impl Miner {
                pub fn new() -> Self { Miner { n: 0 } }
                pub fn digest(&self, data: Vec<u8>) -> i64 { 0 }
            }
            "#,
        );
        let body = code.split("fn actor_#_digest").nth(1).unwrap();
        let read_at = body.find("let data = ").expect("decodes data");
        let assert_at = body.find("r.assert_consumed();").expect("asserts consumed");
        let invoke_at = body.find("crate::api::Miner::digest").expect("invokes");
        assert!(read_at < assert_at && assert_at < invoke_at, "{body}");
        // The synthetic dispatched drop is a request decode too — one handle
        // and nothing else — and it gets the same guard rather than an
        // exemption for being generated.
        let drop_body = code
            .split("fn actor_#___frustrate_drop_Miner")
            .nth(1)
            .expect("the synthetic drop's glue");
        let h_at = drop_body.find("let h = r.read_handle()").expect("decodes the handle");
        let drop_assert = drop_body.find("r.assert_consumed();").expect("asserts consumed");
        let free_at = drop_body.find("actor_drop").expect("drops");
        assert!(h_at < drop_assert && drop_assert < free_at, "{drop_body}");
    }

    /// The one path that deliberately does NOT reach the assert: a sync
    /// `locked` member with `on_contention = "error"` bails out of the middle
    /// of the prelude, having decoded only some of its arguments. Asserting
    /// there would turn contention into a spurious codec panic.
    #[test]
    fn contention_bailout_precedes_the_consumed_assert() {
        let code = emit_src(
            r#"
            #[bridge(locked)] pub struct Cache { x: i32 }
            #[bridge] impl Cache {
                #[bridge(sync, on_contention = "error")]
                pub fn peek(&self, k: i64) -> i64 { 0 }
            }
            "#,
        );
        let body = code.split("fn call_#_peek").nth(1).unwrap();
        let contention_at = body.find("Outcome::Contention").expect("bails on contention");
        let assert_at = body.find("r.assert_consumed();").expect("asserts consumed");
        assert!(contention_at < assert_at, "{body}");
    }

