            #[bridge(data)] pub struct Point { pub x: f64, pub y: f64 }
            #[bridge(data)] pub enum Shape { Dot, Line { len: f64 }, Pair(Point, Point) }
            #[bridge(sync)] pub fn mk() -> Shape { Shape::Dot }
