    #[test]
    fn trait_handles_use_boxed_dyn_type_parameters() {
        let code = emit_src(
            r#"
            #[bridge(frozen)]
            pub trait Store: Send + Sync {
                #[bridge(sync)]
                fn get(&self, key: String) -> Option<String>;
                fn snapshot(&self) -> Box<dyn Store>;
            }
            #[bridge]
            pub fn open(kind: String) -> Box<dyn Store> { todo!() }
            #[bridge(sync)]
            pub fn report(store: &dyn Store) -> String { todo!() }
            "#,
        );
        // sync method: frozen_ref over the boxed dyn type; UFCS resolves the
        // trait method, &Box<dyn Store> deref-coerces at the call.
        assert!(
            code.contains("handle::frozen_ref::<Box<dyn crate::api::Store>>"),
            "{code}"
        );
        assert!(code.contains("crate::api::Store::get(&**this, key)"), "{code}");
        // async method returning a trait object: Arc clone on the caller,
        // handle minted from the returned Box.
        assert!(
            code.contains("handle::frozen_arc::<Box<dyn crate::api::Store>>"),
            "{code}"
        );
        assert!(
            code.contains("handle::frozen_new::<Box<dyn crate::api::Store>>(ret)"),
            "{code}"
        );
        // borrowed trait param on a free function: tagged, and
        // with no bridged implementors the match has just the dyn arm.
        assert!(code.contains("let __tag_store = r.read_u8();"), "{code}");
        assert!(
            code.contains("let store: &dyn crate::api::Store = match __tag_store {"),
            "{code}"
        );
        assert!(code.contains("crate::api::report(store)"), "{code}");
        // drop/finalize exports over the boxed dyn type
        assert!(
            code.contains("frustrate_drop_Store"),
            "{code}"
        );
        assert!(
            code.contains("handle::frozen_drop::<Box<dyn crate::api::Store>>"),
            "{code}"
        );
    }

    /// A consumed trait position takes from the registry its impl tag names,
    /// and what comes out of a bridged implementor's registry is re-boxed into
    /// the `Box<dyn T>` the body was declared with.
    #[test]
    fn a_consumed_trait_takes_behind_its_impl_tag() {
        let code = emit_src(
            r#"
            #[bridge(locked)]
            pub trait Store: Send + Sync {
                fn size(&self) -> usize;
                #[bridge(sync)]
                fn drain(self: Box<Self>) -> usize { 0 }
            }
            #[bridge(locked)]
            pub struct Mem { n: i64 }
            #[bridge]
            impl Store for Mem { fn size(&self) -> usize { 0 } }
            #[bridge]
            pub fn close(s: Box<dyn Store>) -> usize { 0 }
            "#,
        );
        // The carrier: one variant per tag, holding what that tag's registry
        // stores, and one unwrap into the trait object.
        assert!(code.contains("enum __FrOwn_Store {"), "{code}");
        assert!(
            code.contains("Dyn(std::sync::Arc<handle::LockedCell<Box<dyn crate::api::Store>>>),"),
            "{code}"
        );
        assert!(
            code.contains("Mem(std::sync::Arc<handle::LockedCell<crate::api::Mem>>),"),
            "{code}"
        );
        assert!(
            code.contains(
                "Self::Mem(a) => frustrate::handle::locked_take(a).map(|v| { let b: Box<dyn crate::api::Store> = Box::new(v); b }),"
            ),
            "{code}"
        );
        // The consuming **receiver** is tagged, unlike a borrowed one: its
        // Dart member is an extension over the token, resolved statically.
        assert!(code.contains("let __tag_this = r.read_u8();"), "{code}");
        assert!(
            code.contains(
                "0 => __FrOwn_Store::Dyn(unsafe { handle::locked_adopt::<Box<dyn crate::api::Store>>(__h_this) }),"
            ),
            "{code}"
        );
        assert!(code.contains("let this = match own_this.take_dyn() {"), "{code}");
        // A by-value parameter takes the same way, on the pool arm.
        assert!(
            code.contains(
                "1 => __FrOwn_Store::Mem(unsafe { handle::locked_adopt::<crate::api::Mem>(__h_s) }),"
            ),
            "{code}"
        );
        assert!(code.contains("let s = match own_s.take_dyn() {"), "{code}");
        // A borrowed receiver stays untagged: nothing dispatched from a
        // static type, so the fn_id already named the registry.
        assert!(!code.contains("let __tag_this = r.read_u8();\n    let __h_this = r.read_handle();\n    let this = unsafe"), "{code}");
    }

    /// One container that both lends and takes: the argument walk consumes the
    /// **taken** value, and each lent position is acquired from an id gathered
    /// off the staged value before any of it was adopted.
    #[test]
    fn a_container_lends_and_takes_in_one_walk() {
        let code = emit_src(
            "#[bridge(confined)] pub struct D { n: i64 }\n\
             #[bridge] impl D { #[bridge(sync)] pub fn new() -> Self { todo!() } }\n\
             #[bridge(sync)] pub fn f(ps: Vec<(&mut D, D)>) {}",
        );
        // Both halves of every element are staged in one wire order.
        assert!(code.contains("out.push((r.read_handle(), r.read_handle()));"), "{code}");
        // The lent ids come off the staged value, before the adoption moves it.
        let gather = code.find("ids_ps_0.push((*g0).0);").expect("gather");
        let adopt = code.find("let owned_ps =").expect("adopt");
        assert!(gather < adopt, "the ids are read before the adoption\n{code}");
        // Both positions join the duplicate check, with different uses.
        assert!(
            code.contains("alias_entry::<crate::api::D>(*h, frustrate::handle::Use::Mut)"),
            "{code}"
        );
        assert!(
            code.contains("alias_entry::<crate::api::D>(*g1_1, frustrate::handle::Use::Consume)"),
            "{code}"
        );
        // The argument moves out of the taken value, destructuring rather than
        // reading `p.0` and moving `p.1` out of the same place.
        assert!(
            code.contains(
                "let lent_ps = ps.into_iter().map(|a0| { let (b1_0, b1_1) = a0; (unsafe { handle::confined_mut::<crate::api::D>(b1_0) }, b1_1) }).collect::<Vec<_>>();"
            ),
            "{code}"
        );

        // A set or a map that also lends stays **flat** through the take, and
        // is built by the moving walk: rebuilding it earlier would collapse on
        // the id the lent position still is.
        let m = emit_src(
            "#[bridge(confined)] pub struct D { n: i64 }\n\
             #[bridge] impl D { #[bridge(sync)] pub fn new() -> Self { todo!() } }\n\
             #[bridge(sync)] pub fn f(m: std::collections::HashMap<&D, D>) {}",
        );
        assert!(m.contains("collect::<Result<Vec<_>, _>>()"), "{m}");
        assert!(
            m.contains("let lent_m = m.into_iter().map(|(k0, v0)| (unsafe { handle::confined_ref::<crate::api::D>(k0) }, v0)).collect::<std::collections::HashMap<_, _>>();"),
            "{m}"
        );

        // An owned sub-container with no borrow in it is handed over as it
        // stands: the take already built it.
        let o = emit_src(
            "#[bridge(confined)] pub struct D { n: i64 }\n\
             #[bridge] impl D { #[bridge(sync)] pub fn new() -> Self { todo!() } }\n\
             #[bridge(sync)] pub fn f(ps: Vec<(&D, D, Vec<String>)>) {}",
        );
        assert!(
            o.contains("(unsafe { handle::confined_ref::<crate::api::D>(b1_0) }, b1_1, b1_2)"),
            "{o}"
        );
    }

    /// A set or a map holding a handle stages **flat** and is rebuilt only
    /// after every raw has an owner — so whatever the container collapses, it
    /// collapses on the objects rather than on the raws two zero-sized objects
    /// share.
    #[test]
    fn a_set_or_a_map_of_handles_stages_flat() {
        let decl = "#[bridge(confined)] pub struct D { n: i64 } \
                    #[bridge] impl D { #[bridge(sync)] pub fn new() -> Self { todo!() } }";
        let taken = emit_src(&format!(
            "{decl} #[bridge(sync)] pub fn f(s: std::collections::HashSet<D>, \
             m: std::collections::BTreeMap<String, D>) {{}}"
        ));
        assert!(
            taken.contains("let staged_s = { let n = r.read_len(); let mut out = Vec::with_capacity"),
            "{taken}"
        );
        assert!(taken.contains("out.push((k, v));"), "{taken}");
        // The real container is built by the take, not by the decode.
        assert!(
            taken.contains("collect::<Result<std::collections::HashSet<_>, _>>()"),
            "{taken}"
        );
        assert!(
            taken.contains("collect::<Result<std::collections::BTreeMap<_, _>, _>>()"),
            "{taken}"
        );

        // Lent: the same flat staging, and the argument is a container of
        // references built from it.
        let lent = emit_src(&format!(
            "{decl} #[bridge(sync)] pub fn g(s: std::collections::HashSet<&D>, \
             m: std::collections::HashMap<String, &D>) {{}}"
        ));
        assert!(
            lent.contains(
                "let lent_s = staged_s.iter().map(|a0| unsafe { handle::confined_ref::<crate::api::D>((*a0)) }).collect::<std::collections::HashSet<_>>();"
            ),
            "{lent}"
        );
        assert!(lent.contains("collect::<std::collections::HashMap<_, _>>()"), "{lent}");

        // A set or a map with no handle in it decodes as itself, as it always
        // has: the flat staging is for the handle case and nothing else.
        let plain = emit_src(
            "#[bridge(sync)] pub fn h(s: std::collections::HashSet<i64>) -> usize { s.len() }",
        );
        assert!(plain.contains("std::collections::HashSet::with_capacity"), "{plain}");
    }

    /// A trait handle inside a container carries a **per-element** tag: the
    /// staged value is the `(tag, id)` pair, and the acquisition behind it is
    /// chosen per element — inline where nothing has to outlive the call,
    /// through the trait's carrier enum where something does.
    #[test]
    fn a_trait_inside_a_container_is_tagged_per_element() {
        let decl = "#[bridge(locked)] pub trait S: Send + Sync { fn n(&self) -> i64; } \
                    #[bridge(locked)] pub struct M { v: i64 } \
                    #[bridge] impl M { #[bridge(sync)] pub fn new() -> Self { todo!() } } \
                    #[bridge] impl S for M { fn n(&self) -> i64 { 0 } }";
        let lent = emit_src(&format!(
            "{decl} #[bridge] pub fn f(xs: Vec<&dyn S>) -> i64 {{ 0 }}"
        ));
        assert!(lent.contains("out.push((r.read_u8(), r.read_handle()));"), "{lent}");
        assert!(lent.contains("tags_xs_0.push((*g0).0);"), "{lent}");
        assert!(lent.contains("ids_xs_0.push((*g0).1);"), "{lent}");
        assert!(
            lent.contains(
                "0 => __FrArcLock_S::Dyn(unsafe { handle::locked_arc::<Box<dyn crate::api::S>>(*h) })"
            ),
            "{lent}"
        );
        // The lock plan reads the ids alone: a trait position is planned like
        // any other, because which registry answered does not change the id.
        assert!(lent.contains("for (k, &h) in ids_xs_0.iter().enumerate()"), "{lent}");
        assert!(lent.contains(".as_dyn()"), "{lent}");

        // A confined trait needs nothing that outlives the call, so the tag is
        // read where it stands and the arms unify at an annotated `let`.
        let inline = emit_src(
            "#[bridge(confined)] pub trait S: Send { fn n(&self) -> i64; } \
             #[bridge(sync)] pub fn f(xs: Vec<&dyn S>) -> i64 { 0 }",
        );
        assert!(
            inline.contains("let __v: &dyn crate::api::S = match (*a0).0 {"),
            "{inline}"
        );

        // Taken from inside a container: the adoption is the tag's, and the
        // unwrap is the carrier's.
        let taken = emit_src(&format!(
            "{decl} #[bridge] pub fn g(xs: Vec<Box<dyn S>>) -> i64 {{ 0 }}"
        ));
        assert!(
            taken.contains("__FrOwn_S::M(unsafe { handle::locked_adopt::<crate::api::M>(a0.1) })"),
            "{taken}"
        );
        assert!(taken.contains("map(|t0| t0.take_dyn())"), "{taken}");
    }

    /// A trait nothing consumes carries no owned carrier — the enum would name
    /// every implementor's registry type for a take that is never emitted.
    #[test]
    fn an_unconsumed_trait_has_no_owned_carrier() {
        let code = emit_src(
            r#"
            #[bridge(frozen)]
            pub trait Store: Send + Sync { fn size(&self) -> usize; }
            #[bridge(sync)]
            pub fn look(s: &dyn Store) -> usize { 0 }
            "#,
        );
        assert!(!code.contains("__FrOwn_Store"), "{code}");
    }

    #[test]
    fn confined_trait_uses_confined_helpers() {
        let code = emit_src(
            r#"
            #[bridge(confined)]
            pub trait Counter: Send { fn bump(&mut self) -> i64; }
            #[bridge(sync)]
            pub fn mk() -> Box<dyn Counter> { todo!() }
            "#,
        );
        assert!(
            code.contains("handle::confined_mut::<Box<dyn crate::api::Counter>>"),
            "{code}"
        );
        assert!(
            code.contains("handle::confined_new::<Box<dyn crate::api::Counter>>(ret)"),
            "{code}"
        );
        assert!(code.contains("crate::api::Counter::bump(&mut **this)"), "{code}");
    }

    #[test]
    fn tagged_trait_params_cover_all_models() {
        let code = emit_src(
            r#"
            #[bridge(frozen)]
            pub trait Greeter: Send + Sync { fn greet(&self) -> String; }
            #[bridge(frozen)]
            pub struct Robot { x: i64 }
            #[bridge]
            impl Greeter for Robot { fn greet(&self) -> String { todo!() } }
            #[bridge]
            pub fn crowd(g: &dyn Greeter) -> String { todo!() }

            #[bridge(locked)]
            pub trait Store: Send + Sync {
                fn put(&mut self, v: i64);
                #[bridge(sync, on_contention = "error")]
                fn size(&self) -> usize;
            }
            #[bridge(locked)]
            pub struct Vault { x: i64 }
            #[bridge]
            impl Store for Vault {
                fn put(&mut self, v: i64) {}
                #[bridge(sync, on_contention = "error")]
                fn size(&self) -> usize { todo!() }
            }
            #[bridge]
            pub fn fill(s: &mut dyn Store, v: i64) {}
            #[bridge(sync, on_contention = "error")]
            pub fn peek(s: &dyn Store) -> usize { todo!() }
            "#,
        );
        // frozen async: carrier enum unifies Arc<Box<dyn>> and Arc<Robot>
        assert!(code.contains("enum __FrArc_Greeter {"), "{code}");
        assert!(
            code.contains("__FrArc_Greeter::Robot(unsafe { handle::frozen_arc::<crate::api::Robot>(__h_g) })"),
            "{code}"
        );
        assert!(code.contains("crate::api::crowd(g.as_dyn())"), "{code}");
        // locked async mut: arc-lock carrier + write guard in the body
        assert!(code.contains("enum __FrArcLock_Store {"), "{code}");
        assert!(code.contains("let mut guard_s = arc_s.write_dyn().await;"), "{code}");
        assert!(code.contains("crate::api::fill(guard_s.as_dyn_mut(), v)"), "{code}");
        // locked sync: try-read per arm with the contention contract
        assert!(code.contains("=> match unsafe { handle::locked_ref::<crate::api::Vault>(__h_s) }.try_read() {"), "{code}");
        assert!(code.contains("crate::api::peek(guard_s.as_dyn())"), "{code}");
        // unknown tags fail loudly and attributably
        assert!(
            code.contains("panic!(\"frustrate: unknown impl tag {other} for trait `Greeter`\")"),
            "{code}"
        );
    }

    /// A sync `&mut self` method on a `locked` type must emit a `mut` guard
    /// binding.
    ///
    /// Without it the generated `&mut *guard_x` is E0596 — "cannot borrow as
    /// mutable, not declared as mutable" — so the whole crate fails to
    /// compile. The async arm always had this and the sync arm did not, which
    /// meant `#[bridge(sync, on_contention = ...)] fn f(&mut self)` on a
    /// locked type was simply unwritable: codegen accepted it and rustc
    /// rejected the result, with nothing pointing back at the cause.
    ///
    /// Both contention contracts get a case, because the two spellings emit
    /// the binding from different `write!` calls and fixing one would have
    /// left the other broken.
    #[test]
    fn a_sync_mut_method_on_a_locked_type_emits_a_mut_guard() {
        let code = emit_src(
            r#"
            #[bridge(locked)]
            pub struct Counter { n: i64 }
            #[bridge]
            impl Counter {
                #[bridge(sync, on_contention = "block")]
                pub fn bump_blocking(&mut self) -> i64 { self.n += 1; self.n }
                #[bridge(sync, on_contention = "error")]
                pub fn bump_erroring(&mut self) -> i64 { self.n += 1; self.n }
                #[bridge(sync, on_contention = "block")]
                pub fn peek(&self) -> i64 { self.n }
            }
            "#,
        );
        // The two mutable spellings bind `mut`...
        assert!(
            code.contains("let mut guard_this = lock_this.blocking_write()"),
            "blocking &mut self needs a mut guard binding: {code}"
        );
        assert!(
            code.contains("let mut guard_this = match lock_this.try_write()"),
            "erroring &mut self needs a mut guard binding: {code}"
        );
        // ...and the shared receiver still does not, so the fix did not just
        // make every binding `mut` and silence the compiler that way.
        assert!(
            code.contains("let guard_this = lock_this.blocking_read()"),
            "&self must stay an immutable binding: {code}"
        );
    }

    #[test]
    fn synthesized_default_methods_dispatch_via_ufcs() {
        let code = emit_src(
            r#"
            #[bridge(confined)]
            pub trait Tally: Send {
                fn bump(&mut self) -> i64;
                fn describe(&self) -> String { String::new() }
            }
            #[bridge(confined)]
            pub struct Abacus { n: i64 }
            #[bridge]
            impl Tally for Abacus {
                fn bump(&mut self) -> i64 { todo!() }
            }
            "#,
        );
        // The written method and the synthesized default both dispatch
        // statically; UFCS needs only the signature.
        assert!(
            code.contains("<crate::api::Abacus as crate::api::Tally>::bump(this)"),
            "{code}"
        );
        assert!(
            code.contains("<crate::api::Abacus as crate::api::Tally>::describe(this)"),
            "{code}"
        );
    }

    #[test]
    fn trait_impl_methods_dispatch_via_qualified_ufcs() {
        let code = emit_src(
            r#"
            #[bridge(confined)]
            pub struct Doc { x: i64 }
            #[bridge(sync)]
            impl Renderable for Doc {
                fn render(&self) -> String { todo!() }
            }
            "#,
        );
        // Static dispatch on the concrete type; the trait need not be in
        // scope at the generated module.
        assert!(
            code.contains("<crate::api::Doc as crate::api::Renderable>::render(this)"),
            "{code}"
        );
        assert!(code.contains("handle::confined_ref::<crate::api::Doc>"), "{code}");
    }

    /// Each non-actor opaque gets its model's bound stated as a named
    /// assertion, whether or not any member is dispatched — a sync-only frozen
    /// type is still shared by reference across isolates and still drops
    /// wherever the last `Arc` clone dies.
    #[test]
    fn every_non_actor_opaque_asserts_its_models_thread_bound() {
        let code = emit_src(
            r#"
            #[bridge(confined)] pub struct Doc { x: i32 }
            #[bridge(frozen)] pub struct Snap { x: i32 }
            #[bridge(locked)] pub struct Cache { x: i32 }
            #[bridge] impl Doc { #[bridge(sync)] pub fn new() -> Self { Doc { x: 0 } } }
            #[bridge] impl Cache { #[bridge(sync)] pub fn new() -> Self { Cache { x: 0 } } }
            // Deliberately constructor-less: nothing mints a `Snap` handle, so
            // no `frozen_new::<Snap>` call site exists to carry the bound. The
            // assertion is the only thing that states it.
            #[bridge] impl Snap { #[bridge(sync)] pub fn peek(&self) -> i32 { self.x } }
            "#,
        );
        assert!(
            code.contains("const _: fn() = handle::assert_confined::<crate::api::Doc>;"),
            "{code}"
        );
        assert!(
            code.contains("const _: fn() = handle::assert_frozen::<crate::api::Snap>;"),
            "{code}"
        );
        assert!(
            code.contains("const _: fn() = handle::assert_locked::<crate::api::Cache>;"),
            "{code}"
        );
    }

